function makeCounter(start = 0) {
  let count = start;            // private, lives in the closure
  return {
    increment: () => ++count,
    decrement: () => --count,
    value: () => count
  };
}

const a = makeCounter(10);
const b = makeCounter();
a.increment();
a.increment();
b.decrement();
console.log(a.value()); // 12
console.log(b.value()); // -1
console.log(a.count);   // undefined: no direct access

