practice.solution:
function makeCounter(start, step) {
  let count = start;
  return {
    inc() { count += step; },
    dec() { count -= step; },
    reset() { count = start; },
    get() { return count; }
  };
}

const counters = new Map();
const out = [];
for (const raw of stdin.split('\n')) {
  const line = raw.trim();
  if (!line) continue;
  const [cmd, name, a, b] = line.split(' ').filter(Boolean);
  if (cmd === 'create') {
    counters.set(name, makeCounter(Number(a), Number(b)));
    continue;
  }
  const counter = counters.get(name);
  if (!counter) {
    out.push('error: unknown counter ' + name);
    continue;
  }
  if (cmd === 'get') out.push(name + '=' + counter.get());
  else counter[cmd]();
}
console.log(out.join('\n'));

